package com.ifound;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import jakarta.ws.rs.BadRequestException;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class ComplianceEngineTest {
 final ObjectMapper mapper=new ObjectMapper();
 ObjectNode data()throws Exception{return (ObjectNode)mapper.readTree("""
 {"alerts":[],"watch":[{"id":"w1","name":"Alexander Petrov","country":"Russia","dob":"1982-04-16","source":"Test"}],"customers":[],"transactions":[],"rules":{"threshold":80,"amount":100,"velocity":2,"countryWeight":40,"locationWeight":25,"professionWeight":35,"screen":true,"transaction":true}}
 """);}
 ObjectNode customer()throws Exception{return ComplianceEngine.customer(mapper,mapper.readTree("""
 {"first":"Alexandr","last":"Petrov","country":"Russia","dob":"1982-04-16","location":"Moscow","profession":"Engineer","countryRisk":90,"locationRisk":90,"professionRisk":90}
 """),"c1");}
 @Test void unicodeAndFuzzyMatches(){assertEquals(100,ComplianceEngine.similarity("李 明","明 李"));assertEquals(100,ComplianceEngine.similarity("José","Jose"));assertEquals(0,ComplianceEngine.similarity("",""));assertTrue(ComplianceEngine.similarity("Alexandr Petrov","Alexander Petrov")>=80);}
 @Test void screeningCreatesEvidenceAndServerRisk()throws Exception{var data=data();var c=customer();data.withArray("customers").add(c);var result=ComplianceEngine.screen(mapper,data,c);assertEquals(90,result.path("risk").asInt());assertEquals(1,data.withArray("alerts").size());assertEquals("c1",data.get("alerts").get(0).path("customerId").asText());assertTrue(data.get("alerts").get(0).has("evidence"));}
 @Test void stableIdsAndExactDecimalVelocity()throws Exception{var data=data();data.withArray("customers").add(customer());var request=transactionRequest("REF-1");assertEquals("1",ComplianceEngine.transaction(mapper,data,request).path("count").asText());request.put("reference","REF-2");assertEquals("2",ComplianceEngine.transaction(mapper,data,request).path("count").asText());assertEquals("49.99",data.withArray("transactions").get(0).path("amount").asText());assertTrue(data.withArray("transactions").get(0).path("flag").asBoolean());assertEquals(1,data.withArray("alerts").size());}
 @Test void rejectsInvalidPrecision()throws Exception{var data=data();data.withArray("customers").add(customer());assertThrows(BadRequestException.class,()->ComplianceEngine.transaction(mapper,data,mapper.readTree("""
 {"customerId":"c1","amount":"1.001","destination":"India"}
 """)));}
 @Test void disabledRulesDoNotGenerateAlerts()throws Exception{var data=data();((ObjectNode)data.get("rules")).put("screen",false);ComplianceEngine.screen(mapper,data,customer());assertTrue(data.withArray("alerts").isEmpty());}
 @Test void passwordsVerifyWithoutPlaintextStorage()throws Exception{String password="LongRandomPassword123",hash=AuthService.hash(password);assertFalse(hash.contains(password));assertTrue(AuthService.verify(password,hash));assertFalse(AuthService.verify("wrong",hash));}
 @Test void professionIsOptional()throws Exception{var request=customer();request.remove("profession");assertEquals("",ComplianceEngine.customer(mapper,request,"c2").path("profession").asText());}
 @Test void linkedWatchlistUpdatesAndDoesNotMatchItself()throws Exception{var data=data();data.withArray("watch").removeAll();var c=customer();data.withArray("customers").add(c);ComplianceEngine.screen(mapper,data,c);assertEquals(1,data.withArray("watch").size());assertEquals("c1",data.withArray("watch").get(0).path("customerId").asText());assertEquals(0,ComplianceEngine.screen(mapper,data,c).path("matchCount").asInt());c.put("name","Updated Customer");ComplianceEngine.screen(mapper,data,c);assertEquals(1,data.withArray("watch").size());assertEquals("Updated Customer",data.withArray("watch").get(0).path("name").asText());assertTrue(data.withArray("alerts").isEmpty());}
 @Test void watchlistDetailsAreValidatedAndRetained()throws Exception{var watch=mapper.createObjectNode();var request=mapper.createObjectNode().put("first","Alex").put("middle","Test").put("last","Example").put("location","Mumbai").put("profession","Engineer").put("countryRisk","90");ComplianceEngine.watchDetails(request,watch);assertEquals("Mumbai",watch.path("location").asText());assertEquals(90,watch.path("countryRisk").asInt());assertEquals(20,watch.path("professionRisk").asInt());request.put("countryRisk",91);assertThrows(BadRequestException.class,()->ComplianceEngine.watchDetails(request,watch));}
 ObjectNode transactionRequest(String ref){return mapper.createObjectNode().put("customerId","c1").put("amount","49.99").put("destination","India").put("reference",ref).put("beneficiary","Unlisted Recipient").put("beneficiaryAccount","ACCT-1").put("currency","INR").put("channel","Bank transfer").put("purpose","Invoice payment").put("transactionDate",java.time.Instant.now().toString());}
 @Test void beneficiaryScreeningAndDuplicateReferences()throws Exception{var data=data();data.withArray("customers").add(customer());var request=transactionRequest("BEN-1");request.put("beneficiary","Alexander Petrov");var result=ComplianceEngine.transaction(mapper,data,request);assertTrue(result.path("flag").asBoolean());assertEquals(1,result.path("beneficiaryMatches").size());assertEquals("Beneficiary watchlist match",result.path("reasons").get(0).asText());assertEquals(result.path("id"),data.withArray("alerts").get(0).path("transactionId"));assertThrows(jakarta.ws.rs.WebApplicationException.class,()->ComplianceEngine.transaction(mapper,data,request));}
 @Test void disabledScreeningAndRequiredDetails()throws Exception{var data=data();data.withArray("customers").add(customer());((ObjectNode)data.get("rules")).put("screen",false).put("transaction",false);var r=transactionRequest("OFF-1");r.put("beneficiary","Alexander Petrov");assertFalse(ComplianceEngine.transaction(mapper,data,r).path("screened").asBoolean());r.put("reference","OFF-2").remove("purpose");assertThrows(BadRequestException.class,()->ComplianceEngine.transaction(mapper,data,r));}
 @Test void transactionDatesControlVelocityAndRejectFutureDates()throws Exception{var data=data();data.withArray("customers").add(customer());var old=transactionRequest("OLD-1").put("transactionDate",java.time.Instant.now().minusSeconds(172800).toString());ComplianceEngine.transaction(mapper,data,old);var current=ComplianceEngine.transaction(mapper,data,transactionRequest("NOW-1"));assertEquals("1",current.path("count").asText());assertEquals(100,current.path("screeningRules").path("amount").asInt());var future=transactionRequest("FUTURE-1").put("transactionDate",java.time.Instant.now().plusSeconds(3600).toString());assertThrows(BadRequestException.class,()->ComplianceEngine.transaction(mapper,data,future));}
 @Test void phoneticNamePartsMatchWithoutConflictingNames()throws Exception{for(String name:new String[]{"messy","mesi","leoneel","messy leoneel"}){var match=ComplianceEngine.nameMatch(mapper,name,"messi leonel");assertTrue(match.path("score").asInt()>=80,name);assertEquals("Phonetic token match",match.path("matchMethod").asText());}for(String name:new String[]{"John Smith","messy smith","me","Mase"})assertTrue(ComplianceEngine.nameMatch(mapper,name,"messi leonel").path("score").asInt()<80,name);}
 @Test void singleNameCustomerGeneratesPhoneticEvidence()throws Exception{var data=data();data.withArray("watch").removeAll();data.withArray("watch").addObject().put("id","m1").put("name","messi leonel").put("country","Argentina").put("dob","").put("source","Test");var request=customer().put("first","mesi").put("last","");var c=ComplianceEngine.customer(mapper,request,"c1");assertEquals("mesi",c.path("name").asText());var result=ComplianceEngine.screen(mapper,data,c);assertEquals(1,result.path("alertCount").asInt());assertEquals("Phonetic token match",data.withArray("alerts").get(0).path("evidence").path("matchMethod").asText());assertEquals("M200",data.withArray("alerts").get(0).path("evidence").path("matchedTokens").get(0).path("code").asText());((ObjectNode)data.get("rules")).put("threshold",95);assertEquals(0,ComplianceEngine.screen(mapper,data,c).path("alertCount").asInt());}
}
